app_batch.code:
List<Map<String, Object>> results = device.batch(List.of(
    Mobium.step("app_tap", Map.of("target", "text=Network & internet")),
    Mobium.step("app_wait_for", Map.of("target", "text=Internet"))));

app_cookies.code:
for (Map<String, Object> cookie : device.cookies()) {
    System.out.println(cookie.get("name") + "=" + cookie.get("value"));
}

app_devices.code:
for (DeviceInfo d : device.devices()) {
    System.out.println(d.id() + " " + d.platform() + " " + d.state());
}

app_map.code:
for (Element e : device.map()) {
    System.out.println(e.ref() + " " + e.role() + " " + e.label());
}

app_screen.code:
device.screen("small-phone", false);
// ... check the layout ...
device.screen("reset", false);

start.code:
try (Mobium phone = Mobium.builder().platform("ios").app("com.example.shop").start()) {
    Session s = phone.session();
    System.out.println(s.device() + " " + s.driver());
}   // try-with-resources quits: the session ends here

connect.code:
try (Mobium phone = Mobium.connect()) {
    System.out.println(phone.current());
}   // close() leaves the session open for whoever started it

callTimeout.code:
try (Mobium phone = Mobium.builder().callTimeout(Duration.ofMinutes(2)).connect()) {
    phone.map();   // a call past two minutes ends the connection
}

session.code:
try (Mobium phone = Mobium.builder().start()) {
    Session s = phone.session();   // null from connect()
    System.out.println(s.platform() + " " + s.device());
}

quit.code:
Mobium phone = Mobium.builder().app("com.example.shop").start();
try {
    phone.tap("text=Sign in");
} finally {
    phone.quit();   // puts back what the session changed
}

close.code:
Mobium phone = Mobium.connect();
phone.tap("@e2");
phone.close();   // safe to call twice

sessions.code:
for (Map<String, Object> s : device.sessions()) {
    System.out.println(s.get("device") + " " + s.get("platform"));
}

step.code:
var steps = List.of(
    Mobium.step("app_launch", Map.of("app", "com.android.settings")),
    Mobium.step("app_map", null));
device.batch(steps);

MobiumException.code:
try {
    device.tap("text=Continue");
} catch (MobiumException e) {
    System.err.println(e.tool() + " " + e.code() + ": " + e.remedy());
    if (!e.retryable()) throw e;
}

details.code:
try {
    device.batch(List.of(Mobium.step("app_tap", Map.of("target", "text=Sign in"))));
} catch (MobiumException e) {
    System.err.println("stopped at step " + e.details().get("step"));
}

NoSuchElementException.code:
try {
    device.tap("text=Continue");
} catch (dev.mobium.NoSuchElementException e) {   // not java.util's
    device.scrollTo("text=Continue", "down");
}

TimedOutException.code:
try {
    device.waitFor("text=Welcome", WaitFor.visible().timeout(Duration.ofSeconds(3)));
} catch (TimedOutException e) {
    System.err.println(e.getMessage());   // says what was on screen instead
}

UnsupportedException.code:
try {
    device.press("back");
} catch (UnsupportedException e) {   // iOS has no back button
    System.err.println(e.remedy());
}

DeviceNotReadyException.code:
try {
    device.launch("com.example.shop");
} catch (DeviceNotReadyException e) {
    device.screenLocked(false);
    device.launch("com.example.shop");
}

NoDeviceException.code:
try {
    device.map();
} catch (NoDeviceException e) {
    System.err.println("start an emulator first: " + e.remedy());
}

NoSuchAlertException.code:
try {
    device.answerAlert(false);
} catch (NoSuchAlertException e) {
    // nothing was up
}

InvalidArgumentException.code:
try {
    device.tap(null);
} catch (InvalidArgumentException e) {
    System.err.println(e.getMessage());   // names the argument
}

DeviceServerException.code:
try {
    device.tap("@e2");
} catch (DeviceServerException e) {
    if (e.retryable()) device.tap("@e2");
}

InternalException.code:
try {
    device.map();
} catch (InternalException e) {
    System.err.println("mobium bug: " + e.getMessage());
}

intro.code:
try (Mobium device = Mobium.builder().platform("android").app("com.android.settings").start()) {
    for (Element el : device.map()) System.out.println(el.ref() + " " + el.label());
}
